<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Hash;
use Carbon\CarbonImmutable;
class PortalController {
 private function admin(Request $r):void {abort_unless($r->user()->role==='admin',403);}
 private function owner(Request $r,object $x):void {abort_unless($r->user()->role==='admin'||$x->salesperson_id===$r->user()->id,403);}
 private function scope(Request $r,string $table){$q=DB::table($table);return $r->user()->role==='admin'?$q:$q->where('salesperson_id',$r->user()->id);}
 private function audit(Request $r,string $action,string $table,int $id):void {DB::table('audit_logs')->insert(['actor_id'=>$r->user()->id,'action'=>$action,'entity'=>$table,'entity_id'=>$id,'details'=>'{}','created_at'=>now()->utc()]);}
 private function cents($n):int {$a=explode('.',(string)$n);return (int)$a[0]*100+(int)str_pad($a[1]??'',2,'0');}
 private function amount(int $n):string {return intdiv($n,100).'.'.str_pad((string)($n%100),2,'0',STR_PAD_LEFT);}
 private function response(Request $r,array $v){return $r->expectsJson()?response()->json($v):redirect('/')->with('success',__('Saved successfully'));}
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt([...$v,'active'=>true]))return back()->withErrors(['email'=>__('The email or password is incorrect, or your account is inactive.')])->onlyInput('email');$r->session()->regenerate();return redirect()->intended('/');}
 public function profile(Request $r){return view('profile',['user'=>$r->user()]);}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}
 public function token(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string','device'=>'required|string|max:100']);$u=\App\Models\User::where('email',$v['email'])->where('active',true)->first();abort_unless($u&&Hash::check($v['password'],$u->password),401);return ['token'=>$u->createToken($v['device'])->plainTextToken,'user'=>$u];}
 public function snapshot(Request $r){
  $workspace=new \App\Services\Workspace;
  $summary=$workspace->summary($r);
  $v=$r->validate(['page'=>'nullable|integer|min:1','per_page'=>'nullable|integer|min:1|max:50']);
  $page=$v['page']??1;$size=$v['per_page']??50;$data=$summary;$data['pagination']=[];
  foreach(['clients','orders','payments','visits','plans','expenses','reports','workdays'] as $table){
   $rows=$workspace->scope($r,$table)->orderByDesc($table.'.id')->offset(($page-1)*$size)->limit($size+1)->get();
   $data['pagination'][$table]=['page'=>$page,'per_page'=>$size,'has_more'=>$rows->count()>$size];
   $data[$table]=$rows->take($size)->values();
  }
  $data['products']=$workspace->products();
  $data['team']=$workspace->scope($r,'users')->select('id','name','role')->orderBy('id')->offset(($page-1)*$size)->limit($size+1)->get();
  $data['balances']=$workspace->balances($r)->select('orders.*')->selectRaw('COALESCE(verified.paid,0) as paid, orders.total-COALESCE(verified.paid,0) as balance')->orderByDesc('orders.id')->offset(($page-1)*$size)->limit($size+1)->get();
  [, $start,$end]=$workspace->bounds($r);
  $data['monthly']=$workspace->scope($r,'orders')->where('status','confirmed')->where('confirmed_at','>=',$start)->where('confirmed_at','<',$end)->orderByDesc('id')->offset(($page-1)*$size)->limit($size+1)->get();
  foreach(['team','balances','monthly'] as $table){$data['pagination'][$table]=['page'=>$page,'per_page'=>$size,'has_more'=>$data[$table]->count()>$size];$data[$table]=$data[$table]->take($size)->values();}
  return $data;
 }
 public function dashboard(Request $r){$workspace=new \App\Services\Workspace;return view('portal',['data'=>$workspace->summary($r),'products'=>$workspace->products(),'user'=>$r->user()]);}
 public function addClient(Request $r){$v=$r->validate(['name'=>'required|string|max:200','contact'=>'required|string|max:200','phone'=>'nullable|string|max:40','location'=>'required|string|max:500','salesperson_id'=>'nullable|integer|exists:users,id']);$v['salesperson_id']=$r->user()->role==='admin'?($v['salesperson_id']??$r->user()->id):$r->user()->id;$id=DB::table('clients')->insertGetId([...$v,'created_at'=>now()->utc(),'updated_at'=>now()->utc()]);return $this->response($r,['id'=>$id]);}
 public function addOrder(Request $r){$v=$r->validate(['submission_key'=>'required|uuid','client_id'=>'required|integer|exists:clients,id','due_date'=>'nullable|date','items'=>'required|array|min:1|max:100','items.*.product_id'=>'required|integer','items.*.quantity'=>'required|integer|min:1|max:100000','items.*.unit'=>'required|in:bottle,carton','items.*.unit_price'=>['required','regex:/^\d{1,8}(\.\d{1,2})?$/']]);$c=DB::table('clients')->find($v['client_id']);$this->owner($r,$c);return DB::transaction(function()use($r,$v,$c){$old=DB::table('orders')->where('submission_key',$v['submission_key'])->first();if($old){$this->owner($r,$old);return $this->response($r,['id'=>$old->id]);}$total=0;$lines=[];$products=DB::table('products')->whereIn('id',array_column($v['items'],'product_id'))->get()->keyBy('id');foreach($v['items'] as $i){$p=$products->get($i['product_id']);abort_unless($p&&$p->active,422,__('The selected :attribute is invalid.',['attribute'=>__('Product variant')]));$n=$this->cents($i['unit_price'])*$i['quantity'];abort_if($n<=0,422);$total+=$n;$lines[]=[...$i,'product_description'=>$p->category.' '.$p->capacity.' '.$p->fragrance,'line_total'=>$this->amount($n)];}abort_if($total>99999999999999,422);$id=DB::table('orders')->insertGetId(['submission_key'=>$v['submission_key'],'client_id'=>$c->id,'salesperson_id'=>$c->salesperson_id,'total'=>$this->amount($total),'due_date'=>$v['due_date']??null,'status'=>'pending','created_at'=>now()->utc(),'updated_at'=>now()->utc()]);foreach($lines as $line)DB::table('order_items')->insert([...$line,'order_id'=>$id]);$this->audit($r,'submitted','orders',$id);return $this->response($r,['id'=>$id]);});}
 public function confirm(Request $r,int $id){$this->admin($r);return DB::transaction(function()use($r,$id){$o=DB::table('orders')->lockForUpdate()->find($id);abort_unless($o,404);abort_unless($o->status==='pending',409);DB::table('orders')->where('id',$id)->update(['status'=>'confirmed','confirmed_at'=>now()->utc(),'confirmed_by'=>$r->user()->id,'updated_at'=>now()->utc()]);$this->audit($r,'confirmed','orders',$id);return $this->response($r,['status'=>'confirmed']);});}
 public function rejectOrder(Request $r,int $id){$this->admin($r);$v=$r->validate(['reason'=>'required|string|max:1000']);return DB::transaction(function()use($r,$id,$v){$o=DB::table('orders')->lockForUpdate()->find($id);abort_unless($o&&$o->status==='pending',409);DB::table('orders')->where('id',$id)->update(['status'=>'rejected',...$v,'updated_at'=>now()->utc()]);$this->audit($r,'rejected','orders',$id);return $this->response($r,['status'=>'rejected']);});}
 public function addPayment(Request $r){$v=$r->validate(['submission_key'=>'required|uuid','order_id'=>'required|integer|exists:orders,id','amount'=>['required','regex:/^\d{1,8}(\.\d{1,2})?$/'],'reference'=>'required|string|max:200','received_at'=>'required|date']);$o=DB::table('orders')->find($v['order_id']);$this->owner($r,$o);abort_unless($o->status==='confirmed'&&$this->cents($v['amount'])>0,422);$old=DB::table('payments')->where('submission_key',$v['submission_key'])->first();if($old){abort_unless($old->submitted_by===$r->user()->id,403);return $this->response($r,['id'=>$old->id]);}$id=DB::table('payments')->insertGetId([...$v,'submitted_by'=>$r->user()->id,'status'=>'pending','created_at'=>now()->utc(),'updated_at'=>now()->utc()]);return $this->response($r,['id'=>$id]);}
 public function verify(Request $r,int $id){$this->admin($r);return DB::transaction(function()use($r,$id){$p=DB::table('payments')->find($id);abort_unless($p,404);$o=DB::table('orders')->lockForUpdate()->find($p->order_id);$p=DB::table('payments')->lockForUpdate()->find($id);abort_unless($p->status==='pending'&&$o->status==='confirmed',409);$paid=DB::table('payments')->where('order_id',$o->id)->where('status','verified')->get()->sum(fn($x)=>$this->cents($x->amount));abort_if($paid+$this->cents($p->amount)>$this->cents($o->total),422,__('Payment exceeds remaining balance'));DB::table('payments')->where('id',$id)->update(['status'=>'verified','verified_at'=>now()->utc(),'verified_by'=>$r->user()->id,'updated_at'=>now()->utc()]);$this->audit($r,'verified','payments',$id);return $this->response($r,['status'=>'verified']);});}
 public function record(Request $r,string $kind){abort_unless(in_array($kind,['plans','expenses','reports']),404);$v=$r->validate(['submission_key'=>'required|uuid','date'=>'required|date','client_id'=>'nullable|integer|exists:clients,id','budget'=>'nullable|numeric|min:0|max:99999999','notes'=>'required|string|max:10000',...($kind==='reports'?['follow_up_date'=>'nullable|date|after_or_equal:date']:[])]);if(in_array($kind,['plans','expenses']))abort_unless(CarbonImmutable::parse($v['date'])->startOfDay()->gt(now()->startOfDay()),422,__('Plan at least one day in advance'));if(!empty($v['client_id']))$this->owner($r,DB::table('clients')->find($v['client_id']));if($kind==='expenses')abort_unless(!empty($v['client_id']),422,__('Link client travel request to a client'));$old=DB::table($kind)->where('submission_key',$v['submission_key'])->first();if($old){$this->owner($r,$old);return $this->response($r,['id'=>$old->id]);}$id=DB::table($kind)->insertGetId([...$v,'salesperson_id'=>$r->user()->id,'created_at'=>now()->utc(),'updated_at'=>now()->utc()]);return $this->response($r,['id'=>$id]);}
 public function review(Request $r,string $kind,int $id){$this->admin($r);abort_unless(in_array($kind,['plans','expenses','reports']),404);$v=$r->validate(['status'=>'required|in:approved,rejected']);return DB::transaction(function()use($r,$kind,$id,$v){$x=DB::table($kind)->lockForUpdate()->find($id);abort_unless($x&&$x->status==='pending',409);DB::table($kind)->where('id',$id)->update([...$v,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now()->utc(),'updated_at'=>now()->utc()]);$this->audit($r,$v['status'],$kind,$id);return $this->response($r,$v);});}
 public function workday(Request $r){return DB::transaction(function()use($r){DB::table('users')->lockForUpdate()->find($r->user()->id);$old=DB::table('workdays')->where('salesperson_id',$r->user()->id)->whereNull('ended_at')->orderByDesc('id')->first()??DB::table('workdays')->where('salesperson_id',$r->user()->id)->where('date',now('Africa/Nairobi')->toDateString())->first();if($old){abort_if($old->ended_at,409);return ['id'=>$old->id];}return ['id'=>DB::table('workdays')->insertGetId(['salesperson_id'=>$r->user()->id,'date'=>now()->toDateString(),'started_at'=>now()->utc()])];});}
 public function currentWorkday(Request $r){return ['workday'=>DB::table('workdays')->where('salesperson_id',$r->user()->id)->whereNull('ended_at')->orderByDesc('id')->first(),'server_now'=>now()->utc()->toISOString()];}
 public function endWorkday(Request $r,int $id){return DB::transaction(function()use($r,$id){$w=DB::table('workdays')->lockForUpdate()->find($id);abort_unless($w,404);$this->owner($r,$w);if(!$w->ended_at)DB::table('workdays')->where('id',$id)->update(['ended_at'=>now()->utc()]);return ['status'=>'ended'];});}
 public function locations(Request $r,int $id){$v=$r->validate(['points'=>'required|array|min:1|max:200','points.*.submission_key'=>'required|uuid','points.*.latitude'=>'required|numeric|between:-90,90','points.*.longitude'=>'required|numeric|between:-180,180','points.*.accuracy_m'=>'required|numeric|min:0|max:100000','points.*.recorded_at'=>'required|date']);return DB::transaction(function()use($r,$id,$v){$w=DB::table('workdays')->lockForUpdate()->find($id);abort_unless($w,404);$this->owner($r,$w);foreach($v['points'] as $p){$at=CarbonImmutable::parse($p['recorded_at']);abort_unless($at->gte(CarbonImmutable::parse($w->started_at))&&$at->lte($w->ended_at?CarbonImmutable::parse($w->ended_at):CarbonImmutable::now()),422,__('Outside active workday'));$old=DB::table('location_points')->where('submission_key',$p['submission_key'])->first();if($old){abort_unless($old->workday_id===$w->id,403);continue;}DB::table('location_points')->insert([...$p,'workday_id'=>$id,'received_at'=>now()->utc()]);}return ['accepted'=>count($v['points'])];});}
 public function route(Request $r,int $id){$w=DB::table('workdays')->find($id);abort_unless($w,404);$this->owner($r,$w);$q=DB::table('location_points')->where('workday_id',$id)->orderBy('recorded_at')->orderBy('id');if($r->has('page')){$v=$r->validate(['page'=>'required|integer|min:1']);$page=$q->paginate(500,['*'],'page',$v['page']);return ['points'=>$page->items(),'page'=>$page->currentPage(),'last_page'=>$page->lastPage(),'total'=>$page->total()];}return $q->limit(20000)->get();}
 public function visit(Request $r){$v=$r->validate(['submission_key'=>'required|uuid','client_id'=>'required|integer|exists:clients,id','check_in_at'=>'required|date','check_out_at'=>'nullable|date|after_or_equal:check_in_at','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','accuracy_m'=>'required|numeric|min:0','outcome'=>'required|in:order,follow-up,no-sale,payment-follow-up','notes'=>'required|string|max:10000','next_action'=>'nullable|string|max:1000','follow_up_date'=>'nullable|date']);$this->owner($r,DB::table('clients')->find($v['client_id']));$old=DB::table('visits')->where('submission_key',$v['submission_key'])->first();if($old){$this->owner($r,$old);return $this->response($r,['id'=>$old->id]);}$id=DB::table('visits')->insertGetId([...$v,'salesperson_id'=>$r->user()->id,'created_at'=>now()->utc(),'updated_at'=>now()->utc()]);return $this->response($r,['id'=>$id]);}
 public function addUser(Request $r){$this->admin($r);$v=$r->validate(['name'=>'required|string|max:200','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','role'=>'required|in:admin,salesperson']);$u=\App\Models\User::create($v);$this->audit($r,'created','users',$u->id);return $this->response($r,['id'=>$u->id]);}
 public function pricing(Request $r,int $id){$this->admin($r);$v=$r->validate(['unit_price'=>['required','regex:/^\d{1,8}(\.\d{1,2})?$/']]);abort_unless(DB::table('products')->where('id',$id)->exists(),404);DB::table('products')->where('id',$id)->update([...$v,'updated_at'=>now()->utc()]);\Illuminate\Support\Facades\Cache::forget('workspace.products.v1');$this->audit($r,'priced','products',$id);return $this->response($r,['status'=>'updated']);}
}
